import ArgumentParser
import CryptoKit
import Foundation
import OmniMemoCore

/// `codex app-server` over its stdio transport: one JSON-RPC object per line, no `jsonrpc` field.
/// Protocol verified against the schema generated by codex-cli 0.163.0.
final class AppServerConnection: @unchecked Sendable {
  private let process = Process()
  private let input = Pipe()
  private let output = Pipe()
  private var lines: AsyncLineSequence<FileHandle.AsyncBytes>.AsyncIterator
  private var nextID = 0
  private let lock = NSLock()

  init(cwd: URL) throws {
    process.executableURL = URL(fileURLWithPath: "/usr/bin/env")
    process.arguments = ["codex", "app-server", "--listen", "stdio://"]
    process.currentDirectoryURL = cwd
    process.standardInput = input
    process.standardOutput = output
    process.standardError = FileHandle.nullDevice
    try process.run()
    lines = output.fileHandleForReading.bytes.lines.makeAsyncIterator()
  }

  func send(_ object: [String: Any]) {
    guard let data = try? JSONSerialization.data(withJSONObject: object) else { return }
    lock.lock()
    defer { lock.unlock() }
    try? input.fileHandleForWriting.write(contentsOf: data + Data([0x0a]))
  }

  @discardableResult
  func request(_ method: String, _ params: [String: Any]) -> Int {
    lock.lock()
    nextID += 1
    let id = nextID
    lock.unlock()
    send(["id": id, "method": method, "params": params])
    return id
  }

  /// Next server message; nil once the app-server closed its output.
  func next() async throws -> [String: Any]? {
    while let line = try await lines.next() {
      if let object = try? JSONSerialization.jsonObject(with: Data(line.utf8)) as? [String: Any] {
        return object
      }
    }
    return nil
  }

  /// Ends an app-server that ignores interrupts; pending reads then see the closed output.
  func kill() {
    if process.isRunning { process.terminate() }
  }

  func close() {
    try? input.fileHandleForWriting.close()
    if process.isRunning { process.terminate() }
    process.waitUntilExit()
  }
}

extension OmniMemo {
  struct Codex: AsyncParsableCommand {
    static let configuration = CommandConfiguration(
      abstract: "OmniMemo-managed Codex sessions through `codex app-server` (explicit launch only).",
      subcommands: [Run.self])

    struct Run: AsyncParsableCommand {
      static let configuration = CommandConfiguration(
        abstract: "Run one Codex turn in a fresh managed thread; reports runtime events and context usage.")
      @OptionGroup var options: Options
      @Option(help: "Prompt text. The prompt is sent to Codex and never stored.") var prompt: String?
      @Option(help: "Read the prompt from this file instead.") var promptFile: String?
      @Option(help: "OmniMemo task this run works on.") var task: String?
      @Option(help: "read-only (default) or workspace-write.") var sandbox = "read-only"
      @Option(help: "Codex model; default is the user's Codex configuration.") var model: String?
      @Option(help: "Seconds before a running turn is interrupted.") var timeout = 1800
      @Flag(help: "Opt in to a managed fresh-session rollover near the context limit.") var rollover = false
      @Option(help: "Reported context percent that triggers a rollover.") var rolloverAt: Double = 80
      @Option(help: "Most rollovers in this run (one child per parent always).") var maxRollovers = 1

      func validate() throws {
        guard ["read-only", "workspace-write"].contains(sandbox) else {
          throw ValidationError("--sandbox must be read-only or workspace-write")
        }
        guard (prompt == nil) != (promptFile == nil) else { throw ValidationError("give --prompt or --prompt-file") }
        guard (1...100).contains(rolloverAt), (0...3).contains(maxRollovers), timeout > 0 else {
          throw ValidationError("invalid rollover or timeout limits")
        }
      }

      func run() async throws {
        let text = try prompt ?? String(contentsOfFile: promptFile!, encoding: .utf8)
        let ok = try await withStore(options) { store in
          let connection = try AppServerConnection(cwd: store.binding.root)
          defer { connection.close() }
          let run = ManagedCodexRun(
            store: store, connection: connection, sandbox: sandbox, model: model, task: task,
            timeout: timeout)
          return try await run.execute(
            prompt: text, rollover: rollover, rolloverAt: rolloverAt, maxRollovers: maxRollovers)
        }
        // Outside withStore: its error mapping would report an exit code as a storage error.
        if !ok { throw ExitCode(1) }
      }
    }
  }
}

/// One managed run: OmniMemo owns the app-server process, so heartbeats and stale rules apply.
/// Only categories, statuses and reported usage are recorded; prompts and outputs are not stored.
final class ManagedCodexRun: @unchecked Sendable {
  struct Outcome {
    var status: String
    var messages: [String] = []
    var contextPercent: Double?
  }

  let store: MemoryStore
  let connection: AppServerConnection
  let sandbox: String
  let model: String?
  let task: String?
  let timeout: Int
  /// Seconds an interrupted turn gets to stop, and a setup call gets to answer.
  static let killGrace: UInt64 = 30
  static let callTimeout: UInt64 = 120
  private var reportedModel: String?
  // Read by the heartbeat and timeout tasks while the run writes them: locked.
  private let state = NSLock()
  private var currentValue: String?
  private var turnValue: String?
  private var current: String? {
    get { state.withLock { currentValue } }
    set { state.withLock { currentValue = newValue } }
  }
  private var turnID: String? {
    get { state.withLock { turnValue } }
    set { state.withLock { turnValue = newValue } }
  }

  init(store: MemoryStore, connection: AppServerConnection, sandbox: String, model: String?, task: String?, timeout: Int) {
    self.store = store
    self.connection = connection
    self.sandbox = sandbox
    self.model = model
    self.task = task
    self.timeout = timeout
  }

  func execute(prompt: String, rollover: Bool, rolloverAt: Double, maxRollovers: Int) async throws -> Bool {
    _ = try await call(
      "initialize",
      [
        "clientInfo": ["name": "omnimemo", "title": "OmniMemo", "version": "0.3.0"],
        "capabilities": [
          "optOutNotificationMethods": [
            "item/agentMessage/delta", "item/reasoning/textDelta", "item/reasoning/summaryTextDelta",
            "item/reasoning/summaryPartAdded", "item/commandExecution/outputDelta", "item/fileChange/outputDelta",
            "command/exec/outputDelta", "process/outputDelta", "item/plan/delta",
          ]
        ],
      ])
    connection.send(["method": "initialized"])
    let heartbeat = Task {
      while !Task.isCancelled {
        try? await Task.sleep(nanoseconds: 20_000_000_000)
        if let thread = current { await report("heartbeat", thread) }
      }
    }
    defer { heartbeat.cancel() }

    if let task { try await claim(task) }
    var thread = try await startThread()
    var outcome = try await runTurn(thread, prompt)
    var rollovers = 0
    // Safe boundary: the turn completed, so no tool, stream or approval is in flight.
    while rollover, rollovers < maxRollovers, outcome.status == "completed",
      let percent = outcome.contextPercent, percent >= rolloverAt
    {
      guard let next = try await rollOver(from: thread) else { break }
      rollovers += 1
      (thread, outcome) = next
    }
    await report("session.ended", thread)
    current = nil
    return outcome.status == "completed"
  }

  /// Checkpoint first, then one empty child thread that gets the capsule once and must acknowledge it.
  private func rollOver(from parent: String) async throws -> (String, Outcome)? {
    guard try await store.beginRollover(agent: "codex", parent: parent) else { return nil }
    let root = store.binding.root.path
    let capsule = try await store.rolloverCapsule(
      agent: "codex", session: parent, gitBranch: OmniMemo.Rollover.git(root, ["rev-parse", "--abbrev-ref", "HEAD"]),
      gitCommit: OmniMemo.Rollover.git(root, ["rev-parse", "--short", "HEAD"]), changedFiles: [])
    let digest = SHA256.hash(data: Data(capsule.text.utf8)).map { String(format: "%02x", $0) }.joined()
    let token = "ACK " + digest.prefix(16)
    do {
      _ = try await store.prepareRollover(capsule, agent: "codex", digest: digest)
      let child = try await startThread()
      try await store.linkRolloverChild(agent: "codex", parent: parent, child: child)
      let outcome = try await runTurn(
        child,
        capsule.text + "\nFirst line of your reply must be exactly `\(token)`; then resume your own task from the records above, verifying them against the repository.")
      let acknowledged = outcome.messages.first?.split(whereSeparator: \.isNewline).first
        .map { $0.trimmingCharacters(in: .whitespaces).trimmingCharacters(in: CharacterSet(charactersIn: "`")) == token }
        ?? false
      try await store.finishRollover(
        agent: "codex", parent: parent, child: child, acknowledged: acknowledged,
        reason: acknowledged ? "acknowledged" : "child did not acknowledge the capsule digest")
      guard acknowledged else {
        FileHandle.standardError.write(Data(("Rollover not acknowledged; continue manually:\n" + capsule.text).utf8))
        await report("session.ended", child)
        current = parent
        return nil
      }
      await report("session.ended", parent)
      return (child, outcome)
    } catch {
      try? await store.finishRollover(
        agent: "codex", parent: parent, child: nil, acknowledged: false, reason: "child start failed")
      current = parent
      throw error
    }
  }

  /// A todo task becomes doing/codex through the revision check; another owner's task is not taken.
  private func claim(_ id: String) async throws {
    guard let record = try await store.listTasks().first(where: { $0.id == id }) else { throw MemoError.notFound }
    guard record.owner == nil || record.owner == "codex" else {
      throw MemoError.invalid("task is owned by \(record.owner!)")
    }
    guard ["todo", "doing", "review"].contains(record.status) else {
      throw MemoError.invalid("task is \(record.status)")
    }
    // Ownership is per provider, so another live Codex session on the task is checked by session.
    let assigned = Set(try await store.agents().filter { $0.agent == "codex" && $0.taskID == id }.map(\.sessionID))
    let busy = try await store.runtimeAgents().contains {
      $0.client == "codex" && assigned.contains($0.sessionID) && !["stale", "offline"].contains($0.status)
    }
    guard !busy else { throw MemoError.invalid("another Codex session is working on this task") }
    if record.status == "todo" || record.owner == nil {
      _ = try await store.updateTask(
        id: id, expectedRevision: record.revision, status: record.status == "todo" ? "doing" : nil,
        owner: "codex", agent: "codex")
    }
  }

  private func startThread() async throws -> String {
    var params: [String: Any] = [
      "cwd": store.binding.root.path, "sandbox": sandbox, "approvalPolicy": "never", "serviceName": "omnimemo",
    ]
    if let model { params["model"] = model }
    let result = try await call("thread/start", params)
    guard let thread = (result["thread"] as? [String: Any])?["id"] as? String else {
      throw MemoError.invalid("app-server returned no thread")
    }
    reportedModel = result["model"] as? String ?? reportedModel
    current = thread
    await report("session.started", thread)
    if let task { await report("task.assigned", thread, task: task) }
    return thread
  }

  private func runTurn(_ thread: String, _ text: String) async throws -> Outcome {
    let id = connection.request(
      "turn/start", ["threadId": thread, "input": [["type": "text", "text": text]]])
    turnID = nil
    let timer = Task { [self] in
      try await Task.sleep(nanoseconds: UInt64(timeout) * 1_000_000_000)
      if let turn = turnID { connection.request("turn/interrupt", ["threadId": thread, "turnId": turn]) }
      // No turn id yet, or the interrupt was ignored: the limit still holds.
      try await Task.sleep(nanoseconds: Self.killGrace * 1_000_000_000)
      connection.kill()
    }
    defer { timer.cancel() }
    var outcome = Outcome(status: "failed")
    while let message = try await connection.next() {
      if message["id"] as? Int == id, message["method"] == nil {
        if message["error"] != nil { return outcome }
        turnID = ((message["result"] as? [String: Any])?["turn"] as? [String: Any])?["id"] as? String ?? turnID
        continue
      }
      guard let method = message["method"] as? String else { continue }
      let params = message["params"] as? [String: Any] ?? [:]
      if message["id"] != nil {
        // A server request (approval, user input). This run has no approval channel: decline and show blocked.
        connection.send([
          "id": message["id"]!, "error": ["code": -32000, "message": "declined: no approval channel in an OmniMemo managed run"],
        ])
        await report("approval.requested", thread)
        continue
      }
      if let other = params["threadId"] as? String, other != thread { continue }
      let item = params["item"] as? [String: Any]
      switch method {
      case "turn/started":
        turnID = (params["turn"] as? [String: Any])?["id"] as? String ?? turnID
        await report("prompt.received", thread)
      case "item/started":
        if let category = (item?["type"] as? String).flatMap(RuntimeMapping.codexItemCategory) {
          await report("tool.started", thread, category: category)
        }
      case "item/completed":
        if item?["type"] as? String == "agentMessage", let text = item?["text"] as? String {
          outcome.messages.append(text)
          print(text)
        } else if let category = (item?["type"] as? String).flatMap(RuntimeMapping.codexItemCategory) {
          let failed = ["failed", "declined"].contains(item?["status"] as? String ?? "")
          await report(failed ? "tool.failed" : "tool.succeeded", thread, category: category)
        }
      case "thread/tokenUsage/updated":
        let usage = params["tokenUsage"] as? [String: Any]
        let last = (usage?["last"] as? [String: Any])?["inputTokens"] as? Int
        let window = usage?["modelContextWindow"] as? Int
        if let last, let percent = RuntimeMapping.codexContextPercent(lastInputTokens: last, window: window) {
          outcome.contextPercent = percent
          _ = try? await store.recordContext(
            agent: "codex", session: thread, model: reportedModel, usedPercent: percent, windowTokens: window)
        }
      case "turn/completed":
        let status = (params["turn"] as? [String: Any])?["status"] as? String ?? "failed"
        outcome.status = status
        await report(status == "completed" ? "turn.completed" : "turn.failed", thread)
        return outcome
      default:
        continue
      }
    }
    throw MemoError.invalid("codex app-server exited during the turn")
  }

  private func call(_ method: String, _ params: [String: Any]) async throws -> [String: Any] {
    let id = connection.request(method, params)
    // Setup calls answer quickly; a hung app-server must not block the run forever.
    let watchdog = Task { [connection] in
      try await Task.sleep(nanoseconds: Self.callTimeout * 1_000_000_000)
      connection.kill()
    }
    defer { watchdog.cancel() }
    while let message = try await connection.next() {
      guard message["id"] as? Int == id, message["method"] == nil else { continue }
      if let error = message["error"] as? [String: Any] {
        throw MemoError.invalid(method + ": " + String((error["message"] as? String ?? "failed").prefix(160)))
      }
      return message["result"] as? [String: Any] ?? [:]
    }
    throw MemoError.invalid("codex app-server exited")
  }

  private func report(_ type: String, _ thread: String, category: String? = nil, task: String? = nil) async {
    var metadata: [String: MetaValue] = ["observability": .string("managed")]
    if let category { metadata["tool_category"] = .string(category) }
    _ = try? await store.ingest(
      RuntimeEventInput(
        source: "codex_app_server", provider: "codex", externalSessionID: thread, eventType: type,
        modelID: reportedModel, taskID: task, metadata: metadata))
  }
}
